package org.brightstats.desktop;

import javafx.geometry.Insets;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;

/** Task-oriented local start screen; does not open network resources or alter models. */
final class StudioHome {
    private StudioHome(){}
    static Node create(Runnable open,Runnable importData,Runnable readiness,Runnable model,Runnable results,Runnable preferences){return create(open,importData,readiness,model,results,preferences,example->{});}
    static Node create(Runnable open,Runnable importData,Runnable readiness,Runnable model,Runnable results,Runnable preferences,java.util.function.Consumer<StudioExamples.Example> example){
        Label eyebrow=new Label("YOUR RESEARCH STUDIO");eyebrow.getStyleClass().add("eyebrow");Label title=new Label("Turn questions into insight.");title.getStyleClass().add("section-title");Label intro=new Label("Build a model, explore the evidence, and keep every analysis reproducible. Everything stays on your machine.");intro.setWrapText(true);intro.getStyleClass().add("muted");
        FlowPane cards=new FlowPane(16,16);cards.getChildren().addAll(card("01  START","Bring your data","Import CSV, Excel or SPSS with explicit types, missing-data choices and source history.","Import data",importData),card("02  BUILD","Shape your question","Inspect the model canvas, connect constructs, and review the measurement assumptions.","Open model canvas",model),card("03  CHECK","Know what is ready","Review missingness, constant variables, binding problems and method-specific cautions.","Review analysis readiness",readiness),card("04  EXPLORE","Find the evidence","Open result tables, diagnostic notes and graphics. No result is interpreted for you automatically.","Open results",results));
        Button resume=UiAppearance.button("Open a saved project");resume.setOnAction(e->open.run());Button appearance=UiAppearance.button("Make this space yours");appearance.setOnAction(e->preferences.run());VBox hero=new VBox(10,eyebrow,title,intro,new HBox(10,resume,appearance));hero.getStyleClass().add("studio-hero");Label examplesTitle=new Label("Explore a research playground");examplesTitle.getStyleClass().add("section-title");Label examplesNote=new Label("Authored synthetic examples. Opening one asks before replacing unsaved work; calculations run only when you choose them.");examplesNote.setWrapText(true);examplesNote.getStyleClass().add("muted");FlowPane examples=new FlowPane(16,16);for(var item:StudioExamples.all())examples.getChildren().add(card("SYNTHETIC · OFFLINE",item.name(),item.description(),"Open example",()->example.accept(item)));VBox content=new VBox(18,hero,cards,examplesTitle,examplesNote,examples);content.setPadding(new Insets(24));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);cards.prefWrapLengthProperty().bind(scroll.widthProperty().subtract(55));examples.prefWrapLengthProperty().bind(cards.prefWrapLengthProperty());return scroll;
    }
    private static VBox card(String step,String title,String description,String action,Runnable handler){Label small=new Label(step);small.getStyleClass().add("eyebrow");Label heading=new Label(title);heading.getStyleClass().add("card-title");Label body=new Label(description);body.setWrapText(true);body.getStyleClass().add("muted");Button button=UiAppearance.button(action);button.getStyleClass().add("primary-action");button.setOnAction(e->handler.run());VBox box=new VBox(12,new ResearchGlyph(),small,heading,body,button);box.getStyleClass().add("studio-card");box.setPrefWidth(350);box.setMinHeight(215);box.setMaxWidth(420);box.setOnMouseEntered(e->lift(box,-3));box.setOnMouseExited(e->lift(box,0));return box;}
    private static void lift(Node node,double to){if(UiAppearance.effectiveMotion()!=org.brightstats.data.UserPreferences.Motion.FULL){UiMotion.stop(node);node.setTranslateY(0);return;}javafx.animation.TranslateTransition lift=new javafx.animation.TranslateTransition(javafx.util.Duration.millis(120),node);lift.setToY(to);UiMotion.play(node,lift,()->node.setTranslateY(to));}
    static final class ResearchGlyph extends Region {
        final javafx.scene.canvas.Canvas canvas=new javafx.scene.canvas.Canvas(52,40);
        ResearchGlyph(){setPrefSize(52,40);setMinSize(52,40);setMaxSize(52,40);getChildren().add(canvas);setMouseTransparent(true);setAccessibleText("Decorative research graph icon");getProperties().put("brightstats.redraw",(Runnable)this::draw);draw();}
        void draw(){var palette=ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent());var g=canvas.getGraphicsContext2D();g.clearRect(0,0,52,40);g.setFill(javafx.scene.paint.Color.web(palette.accent(),.12));g.fillRoundRect(0,0,52,40,16,16);g.setStroke(javafx.scene.paint.Color.web(palette.accent()));g.setLineWidth(2);g.strokePolyline(new double[]{8,20,32,44},new double[]{29,19,23,10},4);g.setFill(javafx.scene.paint.Color.web(palette.accent()));for(double[] point:new double[][]{{8,29},{20,19},{32,23},{44,10}})g.fillOval(point[0]-2.5,point[1]-2.5,5,5);}
    }
}
